/* 
 * Function to check whether the input is numeric or not
 * This function doesn't validate if the number is valid binary or not
*/
int isNumeric(char *str)
{
    int i = 0;
    int j = 0;
    int isStrNumeric = 0;

    for(i = 0  ;  str[i]!= '\0' ; i++)
    {
        // skip white spaces
        if (str[i] =='')
            continue;
        // Check if it is numeric or not
        for ( j = 0 ; j < 10 ; j++ )
        {
            // Check whether the current character is numeric if true increment j else break
            if(str[i] == (char)(j + 48))
            {
                // increment the char
                j++;
            }
            else
                break;
        }
        isStrNumeric = j - 1;
        // if the string is numeric then break the loop
        if(isStrNumeric == 10 - 1)
            break;
    }
    return isStrNumeric == (i-1);
}

