public class Day8 {
    static String dictionary(List<String> names) {
        var map = new HashMap<String, String>();
        var scanner = new Scanner(System.in);
        String[] nameParts = null;
        for(int i = 0; i < 2; i++) {
            nameParts = scanner.nextLine().split(" ");
            map.put(nameParts[0], nameParts[1]);
        }
        scanner.close();
        int index = 2;
        while (index < names.size()) {
            if(map.containsKey(names.get(index))) {
                String text = map.get(names.get(index));
                if(text.endsWith("."))
                    text = text.substring(0, text.length()-1);
                return text;
            }
            index++;
        }
        return "";
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Input values
        List<String> names = scanner.nextLine().split(" ");

        // Output
        String result = "";
        result = dictionary(names);
        System.out.println(result);

        scanner.close();
    }
}
