public static String getContent(final URL address) throws java.io.IOException {
    java.io.FileInputStream stream = new java.io.FileInputStream(address);
    byte[] buf = new byte[8192];
    java.io.DataInputStream input = new java.io.DataInputStream(stream);

    java.io.StringBuilder output = new java.io.StringBuilder();

    int read;
    do {
        read = input.read(buf);
        if (read > 0) {
            output.append(new String(buf, 0, read));
        }
    } while (read >= 0);
    input.close();

    return output.toString();
}
}

