public class CheckQuizzes extends AbstractCheck {
  private static Course course;
  private static Quiz quiz;
  private static String output;
  private static Course previousCourse;

  private static Path quizzesPath = Paths.get("./test/resources/answers");

  private static Course parse(Path path) {
    try {
      String courseOutput = extractText(path);
      Course course = Course.parse(path.getFileName().toString());

      List<QuizResult> quizResults = QuizResultFactory
       .listFromCourseOutput(course, courseOutput);

      course.setQuizResults(quizResults);

      return course;
    } catch (IOException|TikaException e) {
      e.printStackTrace();
      return null;
    }
  }

  private static boolean exists(String name) {
    return previousCourse.getQuizResults().stream().anyMatch(qr -> name.equals(qr.getName()));
  }

  @Override
  protected List<Course> process(List<Course> courses) {
	course = courses.stream().findFirst().get();

    if (course!= null && output!= null)
      courses.forEach(c -> previousCourse = c);

    Path path = quizzesPath.resolve(course.getFileName());
    Course result = parse(path);

    if (result!= null &&!exists(result.getFileName())) {
      quiz = result;
      output = course.getOutput();
    } else {
      quiz = null;
      output = null;
    }

    return courses;
  }

}
