		if (!userIdResult.isOk()) {
			return ResultCode.ERROR_NO_TOKEN;
		}

		UserAccount account = Database.getInstance().getAccountInfo(userIdResult.getValue());

		if (account == null) {
			return ResultCode.ERROR_NO_TOKEN;
		}

		// Zoek voor deze gebruiker hetzelfde IP
		Collection<Session> allUserSessions = SessionDatabase.getInstance().searchUsingAccount(account);

		for (Session session : allUserSessions) {
			if (session.getUser().equals(account)) {

				if (session.isInLogout()) {
					return ResultCode.ERROR_TOO_MANY_LOGOUT_REQUESTS;
