public static void unzip(File src, File dst) {
	    // Membuka input dan output arsip
	    ZipInputStream zis = new ZipInputStream(new FileInputStream(src));
	    ZipOutputStream zos = new ZipOutputStream(new FileOutputStream(dst));
	    // Iterasi pada anggota arsip
	    ZipEntry e;
	    while ((e = zis.getNextEntry())!= null)
	    {
	        // Mengecek jalur direktori sumber yang bisa mengandung '..'
	        if (!src.getPath().endsWith(File.separator + e.getName()))
	        {
	            // Mengekstrak jika nama file tidak mengandung '..'
	            zos.putNextEntry(new ZipEntry(e.getName()));
	            // Tulis (copy) data file sumber ke tujuan
	            zos.write(zis.readAllBytes());
	            zos.closeEntry();
	        }
	    }
	    // Tutup stream untuk menghemat memori
	    zos.flush();
	    zis.close();
	    zos.close();
	}
