    private static boolean tryToGuessNumber(String inputString) {
        int expectedIntegerInput = Integer.parseInt(inputString);
        int newIntegerInput = 0;

        for(int i = 100; i <= 200; i++){
            newIntegerInput = i;

            if (expectedIntegerInput == newIntegerInput) {
                return true;
            }
        }
        return false;
    }
}
