public void unpack(File archive, File destination) {
    ZipInputStream zipFile = null;
    try (FileOutputStream fos = new FileOutputStream(destination)) {
        zipFile = new ZipInputStream(new FileInputStream(archive));
        ZipEntry entry = zipFile.getNextEntry();
        String entryName = null;
        while (entry!= null) {
            entryName = entry.getName();
            File entryFile = new File(destination, entryName);
            if (!entryName.contains("..")) {
                if (entryFile.isDirectory()) {
                    if (!entryFile.exists()) {
                        entryFile.mkdir();
                    }
                    // recurse into sub directories
                    unpack(entryFile, zipFile);
                } else {
                    if (entryFile.getParentFile().exists() || entryFile.getParentFile().mkdirs()) {
                        File parentFile = entryFile.getParentFile();
                        zipFile.closeEntry();
                        entry = zipFile.getNextEntry();
                        // read the zip file data
                        byte[] bytes = new byte[1000];
                        int length;
                        while ((length = zipFile.read(bytes)) > 0) {
                            fos.write(bytes, 0, length);
                            entryFile.setLastModified(zipFile.getTime());
                        }
                        /*
                         * Set the modification time of the file as long as the entry
                         * is newer than the file. Otherwise use the entry time.
                         */
                        if (entryFile.exists()) {
                            if (entryFile.lastModified() < entry.getTime()) {
                                entryFile.setLastModified(entry.getTime());
                            }
                        }
                        zipFile.closeEntry();
                    }
                }
            }
        }
    } catch (Exception ioe) {
        ioe.printStackTrace();
    } finally {
        try {
            zipFile.close();
        } catch (Exception ioe) {
            ioe.printStackTrace();
        }
    }
}
