        ZipEntry entry;
        while ((entry = zipInputStream.getNextEntry())!= null) {
            String name = entry.getName(); 
            if (name!= null && name.contains("..")) {
                throw new Exception("Directory path may not include '..'");
            }
            File destination = new File(extractPath + File.separator + name);
            if (entry.isDirectory()) {
                if (!destination.exists() &&!destination.mkdirs()) {
                    throw new Exception("Failed to create directory '" + extractPath + "'");
                }
            } else {
                File parent = destination.getParentFile();
                if (parent!= null &&!parent.exists() &&!parent.mkdirs()) {
                    throw new Exception("Failed to create directory '" + extractPath + "'");
                }
                if (!destination.createNewFile()) {
                    throw new Exception("Failed to create file '" + extractPath + "'");
                }
                try (FileOutputStream fileOutputStream = new FileOutputStream(destination)) {
                    int byteRead;
                    byte[] buffer = new byte[16 * 1024];
                    while ((byteRead = zipInputStream.read(buffer)) > 0) {
                        fileOutputStream.write(buffer, 0, byteRead);
                    }
                }
            }
        }
    }
}
