        srcZip = srcZip.getParentFile();
        String zipName = srcZip.getName();
        if (zipName.indexOf('.') > 0) {
            zipName = zipName.substring(0, zipName.indexOf('.'));
        }
        unzip("jar:" + srcZip.getAbsolutePath() + "!/", targetFolder);
    } else {
        ZipInputStream zisfile = new ZipInputStream( new FileInputStream(srcZip));
        ZipEntry ze;
        while ((ze = zisfile.getNextEntry())!= null) {   
            if (ze.isDirectory()) {
                File fl = new File(targetFolder + File.separator + ze.getName());
                if (fl!= null) {
                    fl.mkdirs();
                }
                continue;
            }
            File f = new File(targetFolder + File.separator + ze.getName());
            f.getParentFile().mkdirs();
            FileOutputStream outStream = new FileOutputStream(f);
            byte[] buf = new byte[1024];
            int len;
            while ((len = zisfile.read(buf)) > 0) {
                outStream.write(buf, 0, len);
            }
            outStream.close();
            zisfile.closeEntry();
        }
    }   
}
