int findPosition(File folder, String substring){
    if (folder.getName().startsWith(substring)){
        return folder.getAbsolutePath().length();
    }else{
        int min=folder.listFiles().length;
        int minPos=0;

        for (int i=0;i<folder.listFiles().length;i++){
            if (folder.getName().startsWith(substring)) return folder.getAbsolutePath().length();
            min=findPosition(folder.listFiles()[i], substring);

