public class MimeTypes {
    private ArrayList<MimeType> types = new ArrayList();

/**
 * Adds a new MimeType to the end of the arraylist, and sorts the array to retain
 * sorting order.
 */
public void add(MimeType type){
    types.add(type);
    sort();
}

/**
 * Retrieves a MimeType object that matches a mime_type. Return null if no type
 * is found.
 */
public MimeType find(String mimeType){
    for(MimeType current: types){
        if( current.getMimeType().equals(mimeType) )
            return current;
    }
    return null;
}

/**
 * Sorts the MimeType objects in the list by priority, to prevent lower priority
 * objects from executing before more general objects.
 * Uses the java utility Sorting methods.
 */
private void sort(){
    ArrayList<MimeType> sortedList = new ArrayList();
    while(types.size() > 0){
        MimeType highest = null;
        for(MimeType type : types){
            if(highest == null)
                highest = type;
            else if(type.getPriority() >= highest.getPriority())
                highest = type;
        }
        sortedList.add(highest);
        types.remove(highest);
    }
    types = sortedList;
}

