        /* Filtro para evitar pontos duplos. */
        if (filename.indexOf(';') > 0) {
            return null;
        } else if (filename.indexOf('..') > 0) {
            return null;
        }
        /* Filtro para evitar pontos duplos. */

        String[] tmp = mime_type.split("/");
        /* Divide o mime_type por '/' para ser mais preciso na busca. */
        mime_type = tmp[0].toLowerCase();
        /* Retira o conteúdo da esquerda. */

        if (!mime_type.equals("text")) {
            if (mime_type.equals("mail")) {
                return "mailcap " + filename;
            } else if (mime_type.equals("image")) {
                return "xreader " + filename;
            } else if (mime_type.equals("binary")) {
                return null;
            } else {
                try {
                    return "mimeo " + mime_type + " " + filename;
                } catch (Exception ex) {
                    return "mimeo unknown " + filename;
                }
            }
        } else {
            return "no command for \"text\" type";
        }
    }

