            }
        } catch (Exception e) {}
    }

    /**
     * Retourne le mimetype pour un chemin spécifié.
     */
    public static String mimetype(String filename) {
        String extension = filename.split("\\.")[1];
        return mime_type_table.get(extension);
    }
