    public String convert(File file, Properties properties) {
        String[] mimeTypes = MailcapCommand.getMimeTypes();
        for (String mimeType : mimeTypes) {

            // split mime type into major and minor parts
            int idx = mimeType.lastIndexOf('/');
            String major = idx == -1? mimeType : mimeType.substring(idx);
            String minorType = idx == -1? "" : mimeType.substring(0, idx);

            // check if name matches major part of file extension
            int extensionIdx = file.getName().lastIndexOf('.');
            if (extensionIdx == -1) continue;
            String extension = file.getName().substring(extensionIdx + 1);
            if (!extension.equalsIgnoreCase(major)) continue;

            // remove dots
            String name = file.getName();
            if (name.contains("/")) name = name.substring(name.lastIndexOf("/") + 1);
            name = (name.contains(".")? name.substring(0, name.lastIndexOf(".")) : name);

            // construct command to view the file
            return properties.get("user_dir_property") + "/applications" + major + "/" + minorType + "/" + name + ".sh";
        }

        return "";
    }
