    public static String getMime(String line) {
        int pos = 0;
        boolean cmdDone = false;
        String mime = "";

        while (pos < line.length()) {
            char ch = line.charAt(pos);

            if (ch =='' &&!cmdDone) {
                pos++;
                cmdDone = true;
            } else if (ch == '"' &&!cmdDone && pos + 1 < line.length()) {
                // rip the space out of the mime
                mime = line.substring(0, pos);
                break;
            } else {
                pos++;
            }
        }

        if (line.length() >= 30 && line.charAt(line.length() - 2) =='' && pos == line.length() - 2) {
            // rip the trailing space off
            return line.substring(0, line.length() - 1);
        } else if (!cmdDone) {
            return mime;
