     * 
     * Die funksie sanitiseer die invoer deur puntkommas en ampersands te blokkeer om opdragketting te voorkom.
     */
<|explanation|>

    /**
     * Gee 'n lege reeks waarin hy aan die teken puntkomma vir elke invoersleutel, puntkomma gevolg deur elke spesifiseerde gasheer en ganse ampersand vir elke invoersleutel teruggegee.
     * 
     * Dit verduideliken:
     * `a.input = "test & a\""` => `a.input = "(test & a)\""` (de opdragketting gaan af)
     * `a.input = "test & a\""` => `a.input = "(test & a) \& (a\"\, \$\\n)"` (de invoer bevat spesiale character vir de ampersand)
     * `a.input = "a & b test"` => `a.input = "(a & b) \n (test)"` (de invoer bevat spesiale character vir de puntkomma)
     */
    public static String sanitise(BufferedReader br) {
        try {
            String buffer = br.readLine();
            buffer = buffer.replaceAll("\\\\+", ""); // puntkomma + ampersand, die moet 'n ampersand vir die invoersleutel
            buffer = buffer.replaceAll("\\\\&", ""); // ampersand, die moet 'n ampersand vir die kantanse invoersleutel
            return buffer;
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }

    public static void main(String[] args) {
        try {
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            System.out.println(sanitise(br));
            br.close();
            System.exit(1);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
