static String[] inputSplit(String raw) {
    // Puhdistaa syötteestä puolipisteitä ja &-merkkejä
    BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    try {
        raw = raw.trim();
        while (raw.startsWith("\"")) raw = raw.substring(1);
        int lastPos = raw.length() - 1;
        while (raw.endsWith("\"")) raw = raw.substring(0, lastPos);
        while (raw.contains("&")) raw = raw.replace("&", "&&");
    } catch (Exception e) {
        System.err.println("Virheellinen muoto.");
    }

    String[] lines = raw.split("(\\r\\n|\\n)");
    String[][] newArray = new String[lines.length][2];
    for (int i = 0; i < lines.length; i++) {
        newArray[i][0] = cleanString(lines[i]);
        newArray[i][1] = "true";
    }
    return newStringArray(newArray);
}

static String[] newStringArray(String[][] inArray) {
    String[] tempArray = new String[inArray.length];
    for (int i = 0; i < inArray.length; i++) {
        tempArray[i] = inArray[i][0];
    }
    return tempArray;
}

static String cleanString(String input) {
    String t = input.trim();
    while (t.contains("&&")) t = t.replace("&&", "&");
    // Puhdistetaan teksti puolipisteistä ja &-merkeistä
    t = t.replaceAll("(\\s+)|(", " ").replaceAll("&", " && ").replaceAll("\\s", "");
    t.trim();
    return t.trim();
}
}

