public class Main {
  private static String getPingReply(String host) throws IOException {
    System.out.print(host+": ");
    Process process = Runtime.getRuntime().exec("ping -c 1 "+host);
    DataOutputStream doStream = new DataOutputStream(process.getOutputStream());
    doStream.writeBytes("\n");
    doStream.flush();
    doStream.close();
    BufferedReader br = new BufferedReader(new InputStreamReader(process.getInputStream()));
    return new String(br.readLine().getBytes(), "ISO8859-1");
  }
  public static void main(String[] args) throws IOException {
    System.out.println("Host: "+args[0]);
    System.out.println("Pinging...");
    try {
      System.out.println(getPingReply(args[0]));
    } catch (IOException e) {
      System.out.println("There was an error pinging "+args[0]+": "+e.getMessage());
    }
  }
}
