    public static String nettoi(String entree) throws Exception {
        String s;

        if (entree == null) {
            throw new Exception("Error: Null value");
        }

        s = entree.trim();

        if (s.length() == 0) {
            throw new Exception("Error: Empty line");
        }

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '.' || s.charAt(i) == ';' || s.charAt(i) == '@') {
                throw new Exception("Error: Line is not well-formed");
            }
        }

        return s;
    }
}

