import java.io.InputStreamReader;

public class Solution007 {
    public static int calculateDays(int months) {
        if (months < 0) {
            throw new IllegalArgumentException("Too many months");
        }
        int days = 0;
        int i = 1;
        while (i <= months) {
            if (i == 1 || i == 3 || i == 5 || i == 6 || i == 7 || i == 10 || i == 12) {
                days += 31;
            } else if (i == 4 || i == 8 || i == 9 || i == 11) {
                days += 30;
            } else if (i == 2) {
               ++days;
            }
            ++i;
        }
        return days;
    }

    public static void main(String[] args) throws IOException {
        InputStreamReader reader = new InputStreamReader(System.in);
        BufferedReader bufferedReader = new BufferedReader(reader);
        Integer amountOfMonths = Integer.valueOf(bufferedReader.readLine().trim());
        System.out.println(calculateDays(amountOfMonths));
    }
}
