public static String getGreetingMessage(String input) {
    // Get initial capitals
    Set<String> initialCaps = new HashSet<>();
    for (int charIndex = 0; charIndex < input.length(); charIndex++) {
        char charValue = Character.toLowerCase(input.charAt(charIndex));
        if (Character.isLetter(charValue)) {
            initialCaps.add(String.valueOf(charValue));
        }
    }

    String greeting = "Hello ";
    Iterator<String> initialCapIt = initialCaps.iterator();
    int i = 0;
    // Add the initial capitals in
    while (initialCapIt.hasNext()) {
        if (i > 0) {
            greeting += " ";
        }
        greeting += String.valueOf(initialCapIt.next());
        i++;
    }
    // Ask after the capitals
    greeting += ", how are you today?";

    return greeting;
}
