public static String scrubHtml(String str) {
    Pattern scarePattern = Pattern.compile(
        "(<script.*?>)(.*?)(</script.*?>)", 
        Pattern.DOTALL
        | Pattern.CASE_INSENSITIVE);
    Matcher match = scarePattern.matcher(str);
    StringBuffer buf = new StringBuffer(str.length() + 1024);

    while (match.find()) {
        byte[] bytes = null;

        // match.group(3) contains the matched content.  This is what we won't 
        // want to output on the page so we create a new bytes array to put bytes 
        // in.
        try {
            bytes = match.group(3).getBytes(
                    ("\u0000" + match.group(3) + "\u0000").getBytes("ISO-8859-1"));
        }
        catch (UnsupportedEncodingException e) {
            // This should never happen!  But just make sure.
            throw new IllegalStateException(
               "The default encoding for this JVM is not supported");
        }

        // Escape those characters that are unsafe and output
        try {
            match.appendReplacement(buf, "");
            buf.append(
                (htmlEscape? StringEscapeUtils.escapeHtml(
                    new String(bytes, "ISO-8859-1"), false) : new String(bytes, "UTF-8")));
        }
        catch (UnsupportedEncodingException e) {
            // This should never happen!  But just make sure.
            throw new IllegalStateException(
               "The default encoding for this JVM is not supported");
        }
    }

    // Put the remainder of the string into the buffer too.
    buf.append(match.group(0));

    // Get rid of all remaining patterns!
    match.appendTail(buf);

    return buf.toString();
}
