public class JavaExplainedTokenizer implements Tokenizer {

    @Override
    public String[] tokenize(String text) {
        List<Token> tokens = new ArrayList<>();
        tokenize(tokens, text);
        return tokens.stream().map(Token::getText).toArray(String[]::new);
    }

    @Override
    public void tokenize(List<Token> arrayTokens, String text) {
        Pattern pattern = Pattern.compile("^\\s*(" + Paragraph.PATTERN + ")?(.*?)(\\{\\|assistant\\}|\\{\\|system\\})?\\s*$");

        List<String> lines = Arrays.asList(text.replaceAll("\\<\\!\\-", "\<").split("\\n"));
        int startToken = 0;
        for (int index = 0; index < lines.size(); index++) {
            String s = lines.get(index);
            if ("// >><".equals(s)) {
                continue;
            }
            Matcher m = pattern.matcher(lines.get(index));

            if (m.matches()) {
                startToken = index;
                arrayTokens.add(new Token(0, text.substring(0, m.start()), m.start(), m.end()));
                return;
            }

            arrayTokens.add(new Token(startToken, s, index, index + 1));
        }
    }

