def preprocess_template (template):
    """Mengganti pengaturan variabel Jinja2, misalnya menjadi tanda - dasar."""
    def get_replace_from_jinja2 ():
        for attr in dir (jinja2):
            if attr.startswith ('CFG_'):
                yield (getattr (jinja2, attr), attr.replace ('CFG_', '-'))

    def replace (string):
        _return = string.isupper ()
        for item in get_replace_from_jinja2 ():
            string = string.replace (item[0], item[1])
            _return = True
        return (_return, string)

    def replace_all_in_template (template):
        _return = False
        for key, value  in replace (template):
            if not key:
                continue
            template = template.replace (key, value)
            _return = True

        return (_return, template)

    while True:
        ret, tpl = replace_all_in_template (template)
        if not ret:
            break

        template = tpl

    return template

