    static List<String> tokenizeString(String str) {
        List<String> tokens = new ArrayList<>();
        // Replace, from input with spaces to facilitate tokenization
        String[] values = str.split(",");
        for (String value : values) {
            // For blank spaces, we append a space
            if (value.isBlank()) {
                tokens.add(" ");
            } else {
                // For non- blank spaces, we append the original string
                tokens.add(value);
            }
        }

        return tokens;
    }

    static int countTokens(String str) {
        // Get tokens
        return tokenizeString(str).size();
    }
