const canConvert = function (initialStatus, powerRules, finalStatus) {
    for (let i = 0; i < initialStatus.length; i++) {
      if (powerRules(i) == 1) {
        if (initialStatus[i] == 0) {
          return false
        }
      } else if (powerRules(i) == 0) {
        if (initialStatus[i] == 1) {
          return false
        }
      } else {
        initialStatus[i] = powerRules(i)
      }
    }
    return initialStatus === finalStatus
  }


  export default canConvert
