		StringBuilder builder = new StringBuilder();
		for (String next : data) {
			if(builder.length()!= 0) {
				builder.append(delimter);
			}
			builder.append(next);
		}
		return builder.toString();
	}

	public static String wrapWithQuotation(String content) {
		return "\"" + content + "\"";
	}

