import java.util.Set;

/**
 *
 * @author  <>
 */
public class ClassifiedCode extends Code {
    Classifier classifier;

    public ClassifiedCode(Code c, Classifier cl){
        this.classifier = cl;
        this.setValue(getValue(c.getValue()));
        this.setLanguage(c.getLanguage());
        this.setLanguage(c.getLanguage());
        this.setLines(c.getLines());
    }

    private String getValue(String codigo) {
        try {
            String[] code = codigo.split("\\r?\\n");
            for (int i = 0; i < code.length; i++) {
                code[i] = clasify(code[i]);
            }
            return String.join("\n", code);
        } catch (Exception e) {
        }

        return codigo;
    }

    private String clasify(String line) {
        String[] words = line.trim().split("[\\s+]");
        String ret = "";
        for (int i = 0; i < words.length; i++) {
            if (Classifier.getKnownWords().contains(words[i].toLowerCase())) {
                words[i] = clasificable(words[i]);
            } else {
                continue;
            }
            ret+=words[i] ;
        }

        return ret;
    }

    private String clasificable(String word) {
       Classifier.knownWords.add(word);
        for (Classifier classifier : Classifier.getClassifers()) {
            if (classifier.clasificable(word.toLowerCase())) {
                return classifier.toString();
            }
        }
        return word;
    }

    public Code getCode() {
        return new Code(getValue(), getLanguage());
    }
    public static Set<Classifier>classifers;

    public static Set<String> getClassification(){
        return Classifier.classification;
    }

