    bodyHTML = bodyHTML.replace("<", "[TAGHTMLSTART][BETA][ETAGHTMLSTART]:");
    bodyHTML = bodyHTML.replace(">", "[TAGHTMLEND][BETA][ETAGHTMLEND]:");
    // Rimuove le altre tag HTML, perchè quelle non voglio
    bodyHTML = bodyHTML.replace("<title>", "[BETA][ETITLE]");
    bodyHTML = bodyHTML.replace("</title>", "[BETA][ETITLE]");
    bodyHTML = bodyHTML.replace("<meta", "[BETA][ETITLE]");
    bodyHTML = bodyHTML.replace("<body>", "[BETA][ETITLE]");
    bodyHTML = bodyHTML.replace("</body>", "[BETA][ETITLE]");
    // Qui si rimuovono i tag script di cui sopra, che hanno sostituito i tag dell'HTML
    bodyHTML = bodyHTML.replace("[TAGSCRIPT]", "<script");
    bodyHTML = bodyHTML.replace("[ETAGSCRIPT]", "</script>");
    bodyHTML = bodyHTML.replace("[TAGHTMLSTART][BETA][ETAGHTMLSTART]:", "<");
    bodyHTML = bodyHTML.replace("[TAGHTMLEND][BETA][ETAGHTMLEND]:", ">");
