        int sizeOfDataInZip = new Long(zipFile.size()).intValue();
        byte[] contentOfFile;
        if (sizeOfDataInZip > 8192) {
            contentOfFile = zipFile.getInputStream().readNBytes(8192);
        } else {
            contentOfFile = zipFile.getInputStream().readAllBytes();
        }
        Result r = new Result(new String(contentOfFile));
