def slugify(s):
    # Replace accented characters with unaccented characters
    unaccented = str.translate(str.lowercase(), string.maketrans(
        "åäéèíïîöõñüæç", "aeiouainoeunuc"))
    return ''.join(
        (x if x not in unaccented else'' + x +'').title() for x in str(s).lower()
        ).rstrip()


