    public String kod_hesapla(int product_id) {
        String kod = String.format("%04d", product_id);
        char digit1 = kod.charAt(0), 
             digit2 = kod.charAt(1), 
             digit3 = kod.charAt(2), 
             digit4 = kod.charAt(3); 
        char[] digits = {digit1, digit2, digit3, digit4}; 

        int result = 0 ; 
        for (int productIndex= 0; productIndex < digits.length; productIndex++) {
            result += Character.digit(digit1, 10) * (productIndex + 1);
        }
        return Integer.toString(result);
    }


