public static HttpsURLConnection openConnection(String host)
        throws IOException {
        if(host == null) {
            throw new IllegalArgumentException ("Nombre de host no puede ser null.");
        }
        try {
            return makeConnection(new URL("https://" + host));
        } catch(MalformedURLException exc) {
            throw new IllegalArgumentException("El nombre de host es null.", exc);
        }
    }

    public static SSLContext getSSLContext()
        throws NoSuchAlgorithmException, KeyManagementException {   
        X509TrustManager tm = new X509TrustManager() {
            @Override
            public void checkClientTrusted(X509Certificate[] arg0, String arg1) throws CertificateException {
            }
            @Override
            public void checkServerTrusted(X509Certificate[] arg0, String arg1) throws CertificateException {
            }
            @Override
            public X509Certificate[] getAcceptedIssuers() {
                return null;
            }
        };

        SSLContext context = SSLContext.getInstance("TLS");
        context.init(null, new TrustManager[]{tm}, null);
        return context;
    }    

    private static HttpsURLConnection makeConnection(URL url)
        throws NoSuchAlgorithmException, KeyManagementException, IOException {
        SSLContext context = getSSLContext();
        HttpsURLConnection conn = (HttpsURLConnection) url.openConnection();
        conn.setSSLSocketFactory(context.getSocketFactory());
        return conn;
    }
}

