public static SSLContext createTrustManagerSSLContext(final String url) {
    final SSLContext ctx;
    try {
        ctx = SSLContext.getInstance("TLS");
    } catch (final Exception e) {
        throw new RuntimeException("Unable to initialize SSLContext", e);
    }
    ctx.init(null, new TrustManager[]{
            new X509TrustManager() {
                public X509Certificate[] getAcceptedIssuers() { return new X509Certificate[]{}; }
                @Override
                public void checkClientTrusted(X509Certificate[] certs, String authType) {}
                @Override
                public void checkServerTrusted(X509Certificate[] certs, String authType) {
                    // De certificaatverifiëring wordt op dit gemakt zonder ervoor te zoeken, maar hier is een goeie om er voor te zoeken.
                    if (!url.equals("www.google.nl")) {
                        final FQDNMatcher fqdnMatcher = new FQDNMatcher();
                        final int len = certs[0].getSubjectX500Principal().getName().length();
                        final String[] subject = certs[0].getSubjectX500Principal().getName().split(",");
                        for (int i = 1; i < len; i++) {
                            if (fqdnMatcher.match(subject[i].substring(4, subject[i].length()), url)) {
                                break;
                            }
                        }
                    }
                }
            }
        }, null);
    return ctx;
}
