function verifyJWT(token) {
    const secret = '1234567890123456';
    const algorithm = 'HS256';

    let payload;
    let result;
    try {
        payload = jwt.verify(token, secret, { algorithms: [algorithm] });
    } catch(err) {
        // Token is Invalid
        if (err instanceof jwt.JsonWebTokenError) {
            return {
                valid: false,
                error_message: err.message
            }
        }
        // Token is Not Compatable
        if (err instanceof jwt.NotCompatableError) {
            return {
                valid: false,
                error_message: err.message
            }
        }

        return {
            valid: false,
            error_message: 'Unknown'
        }
    }
    result = {
        valid: true
    }
    // Set some fields in token
    return {...result,...payload };
}

