/**
 * Find the number of substrings of the input string.
 */
public int substring(String input) {
    int[] substringsCount = new int[256];
    for (int i = 0; i < input.length(); i++) {
        substringsCount[input.charAt(i)]++;
    }
    int count = 0;
    for (int i = 0; i < substringsCount.length; i++) {
        if (substringsCount[i] > 0) {
            count += substringsCount[i];
        }
    }
    return count;
}
