class HeaderValidator {
  private static final String REG_EX = "^([A-Z]+)/([1-9]\\d*)$";

  public boolean isHttpHeader(String header) {
    final Pattern pattern = Pattern.compile(REG_EX);
    final Matcher matcher = pattern.matcher(header);
    final boolean isProtocolValid = matcher.matches();

    if (isProtocolValid) {
      final String HTTP_REGEX = "([A-Z]+) ([1-9]\\d*) (HTTP/1|HTTP/2[.0-9]*[.0-9]*)";
      final Pattern httpPattern = Pattern.compile(HTTP_REGEX);
      final Matcher httpMatcher = httpPattern.matcher(header);
      return httpMatcher.matches();
    } else {
      return false;
    }
  }
}
