        if(!header.matches("^[a-zA-Z][a-zA-Z0-9=\\._-]+[a-zA-Z0-9]+$")) {
            // Checki ei toimi, koska paitsi suuret ja pienet aakkosnimet voi olla sallittuja joko edellä tai alkunykyissä.
            return false;
