     * Permite acesso a um texto de um arquivo.
     */
    StringBuilder buscarConteudoDeArquivo(File nomeArquivo) throws Exception {
        StringBuilder conteudo = new StringBuilder();

        FileReader frArquivo = new FileReader(nomeArquivo);
        BufferedReader brArquivo = new BufferedReader(frArquivo);

        String sArquivo;
        while((sArquivo = brArquivo.readLine())!= null) {
            conteudo.append(sArquivo);
            conteudo.append("\n");
        }

        frArquivo.close();
        brArquivo.close();

        return conteudo;
    }

