    public static void main(final String[] args) throws Exception {
        // Read arguments
        if (args.length < 2) {
            throw new Exception("Wrong argument!");
        }
        final File file = new File(args[0]);
        final String name = args[1];

        // Load file
        final ArrayList<String> source = new ArrayList<String>(8192);
        {
            final BufferedReader reader = new BufferedReader(new FileReader(file.toURI().toString()), 8192);
            String line = null;
            while ((line = reader.readLine())!= null) {
                source.add(line.trim());
            }
            reader.close();
        }

        // Paste the code
        final StringBuilder destination = new StringBuilder(8192);
        {
            final int size = source.size();
            for (int i = 0; i < size; ++i) {
                final String element = source.get(i);
                if (element == null) continue;
                destination.append(element).append('\n');
            }
        }

        // File code
        System.exit(
            (new File(name)).createNewFile()? 0 : 1
        );
    }
}
