package com.mow.mowserver.handlers.request;

import com.mow.mowserver.handlers.BaseHandler;
import com.mow.mowserver.utils.HelperFunctions;
import com.mow.mowserver.utils.PostParser;
import com.sun.net.httpserver.HttpExchange;
import org.json.JSONObject;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class FetchAnswerHandler extends BaseHandler {
    @Override
    public String handle(HttpExchange exchange, JSONObject json) {
        StringBuilder builder = new StringBuilder();
        try{
            InputStreamReader streamReader = new InputStreamReader(exchange.getRequestBody(), "UTF-8");
            BufferedReader bufReader = new BufferedReader(streamReader);

            json = PostParser.parseRequest(bufReader);
        } catch (IOException e) {
            e.printStackTrace();
        }

        String answerId = (String) json.get("answerId");
        String language = (String) json.get("language");

        switch (language) {
            case "Java":
            case "C#":
            case "C++":
            case "Python":
            case "Other":
            case "HTML":
            default:
                builder.append(answerRepository.getAnswer(answerId));
                break;
        }

        return builder.toString();
    }
}
