import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.util.Base64;

public class ClassX {
    /**
     * Deserializa dados do usuário a partir de uma string codificada em base64.
     * 
     * O código permite injeção de classes maliciosas com nomes disparados
     */
    public static ClassX deserialize(String data) throws Exception {
        // Data de entrada é convertida para base64
        byte[] bytesFromData = Base64.getDecoder().decode(data.getBytes());

        // Objeto de saída criado
        ClassX newInstance = new ClassX();

        // Objeto de entrada é instanciado
        ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(bytesFromData);
        ObjectInputStream objectInputStream = new ObjectInputStream(byteArrayInputStream);

        // Objeto de saída possui parâmetros lidos do objeto de entrada
        newInstance.setName(objectInputStream.readUTF());
        newInstance.setSuperClass((ClassX)objectInputStream.readObject());
        newInstance.setMethods(objectInputStream.readObject());

        objectInputStream.close();
        byteArrayInputStream.close();

        return newInstance;
    }
}


