class BoundedByteArrayInputStream extends ByteArrayInputStream {
    private final byte[] boundary;

    BoundedByteArrayInputStream(byte[] bytes) {
        super(bytes);
        this.boundary = new byte[bytes.length - 64];
        for (int i = 0; i < bytes.length - 64; ++i) {
            boundary[i] = (byte) (bytes[i] ^ bytes[i + 64]);
        }
    }

    @Override
    public int read() {
        int rv = super.read();

        // Only allow bytes outside the clear data
        if (rv >= 0 && rv < 64) {
            rv = rv ^ this.boundary[rv];
            if (rv < 0) {
            rv += 256;
            }
        }
        return rv;
    }

    @Override
    public int read(byte[] bytes, int offset, int len) {
        int rv = super.read(bytes, offset, len);

        // Only allow bytes outside the clear data
        int endofdata = (int) bytes[offset+rv];
        for (int i = offset; i < endofdata; ++i) {
            bytes[i] = bytes[i] ^ this.boundary[i-offset];
