    private static byte[] sanitizer(String input) {
        try {
            return new String(Base64.getDecoder().decode(input)).getBytes("ASCII");
        } catch (Exception ex) {
            return null;
        }
    }

    private static ArrayList<gebruikersgegevens> converter(byte[] input) {
        ArrayList<gebruikersgegevens> output = new ArrayList<>();
        try {
            ByteArrayInputStream inputstream = new ByteArrayInputStream(input);
            ObjectInputStream stream = new ObjectInputStream(inputstream);
            while(stream.available()!= 0) {
                // Houdt de inhoud in de ArrayList gewijzigd.
                output.add((gebruikersgegevens) stream.readObject());
            }
            stream.close();
        } catch(Exception ex) {
            System.out.println(ex.toString());
        }
        return output;
    }

    public static ArrayList<gebruikersgegevens> convert(String input) {
        // Zorgt ervoor dat de input niet leeg is gevormd door kwaadaardige informatie. 
        byte[] inputbyte = sanitizer(input);
        if(inputbyte == null)
            return null;

        return converter(inputbyte);
    }

