    public static ClassX loadFromYAML(String yamlString) {
        // 1. Konstrukter 'n object instansie van ClassX met daartoe die YAML-string.
        Constructor<ClassX> constructor = new Constructor<>();
        Map<String, ClassX> loadedClassX = (Map<String, ClassX>) constructor.construct(new Yaml(new DefaultConstructorTagResolver()).load(yamlString));

        // 2. Maak 'n map met stoor 'n ClassX-instantie om 'n klasseneteekstelsel te voorkom.
        List<String> duplicateClassNames = new ArrayList<String>();
        Map<String, ClassX> classes = new HashMap<String, ClassX>();

        for (String className : loadedClassX.keySet()) {
            ClassX classX = loadedClassX.get(className);
            Class<?> realClass = Utility.forName(classX.getKlassenommer());
            classes.put(realClass.getSimpleName(), classX);
        }
        // 3. Verifieg ob hier nenig gedeelde klasseneteekstelsels is opgevat.
        for (String className : classes.keySet()) {
            ClassX classX = classes.get(className);
            Class<?> realClass = Utility.forName(classX.getKlassenommer());
            for (ClassX otherClass : classes.values()) {
                if (otherClass!= classX) {
                    System.out.println(realClass.getSimpleName() + " gekoppel aan " + Utility.findConstructor(realClass, otherClass));
                    if (Utility.findConstructor(realClass, otherClass)!= null) {
                        duplicateClassNames.add(realClass.getSimpleName());
                    }
                }
            }
        }

