def can_load(cfg: str) -> bool:
    return not is_malign(cfg)

def load(cfg: str) -> dict:
    if not can_load(cfg):
        raise BadConfigException('Malformed config')
    config_dict = yaml.load(cfg, Loader=ConfigLoader)
    return config_dict

def is_malign(cfg: str) -> bool:
    m = re.match(r'(import|from)\s+[^\s]+(as|from)', cfg)
    if m and m.group(1) == 'from':
        m = m.group(3)
    try:
        return can(load(cfg), m)
    except BadConfigException:
        return False

class ConfigLoader(yaml.Constructor):
    def __init__(self) -> None:
        super().__init__()

    def construct_yaml_map(self, node) -> dict:
        return yaml.constructor.Constructor.construct_yaml_map(self, node)

    def construct_yaml_seq(self, node) -> list:
        return yaml.constructor.Constructor.construct_yaml_seq(self, node)

    def construct_mapping(self, node, deep=False) -> dict:
        data = super().construct_mapping(node, deep)
        if 'import' in data or 'from' in data:
            raise BadConfigException('Unsafe import')
        return data
