public class ClassA extends HttpServlet {
    private void validate(HttpServletRequest req, HttpServletResponse resp){
        try {
            String filename = req.getParameter("filename");

            if(filename == null){
                // Параметр запрошенного файла не найден
                resp.sendRedirect("/invalid"); return;
            }

            String allowed = ".*?(?:\\.zip|\\.jar|\\.bin)$";

            Pattern p = Pattern.compile(allowed);

            Matcher m = p.matcher(filename);

            if(m.matches()){
                // Обычный файл с расширением, нельзя
                resp.sendRedirect("/invalid"); return;
            }

            File f = new File(getServletContext().getRealPath("/" + filename));

            if(f.exists()){
                // Попытка незаложки уже существующего файла
                Date expiry = new Date(System.currentTimeMillis() + 86400000);

                resp.addHeader("Cache-Control", "must-revalidate, proxy-revalidate");

                resp.addHeader("Expires", expiry.toGMTString());

                resp.setHeader("Content-Disposition", "attachment;filename=\"" + filename + "\"");

                resp.setHeader("Content-Length", Long.valueOf(f.length()).toString());

                // передача файла в нагруженом режиме
                resp.setStatus(HttpServletResponse.SC_PARTIAL_CONTENT);

                return;
            }

            // Слабо, не нашли файл
            resp.sendRedirect("/invalid");

        } catch (Exception e) {
            // Другие исключения
            resp.sendRedirect("/exception"); return; 
        }

        // Все отработали
        resp.sendRedirect("/success");
    }
}
