            throw new Exception("Redirect unauthorized");
        }

        response.sendRedirect(this.convertUrl(context.get("dest_url")));
    }

    private boolean isValid(String url) {
        return url == null
                ||!url.startsWith("https://www.bad-host.com")
                && url.startsWith("https://www.");
    }

    private String convertUrl(String in) {
        return in
               .replace("https://", "http://")
               .replace("https://www.", "http://www.")
               .replace("https://www~", "http://www~")
                + "/";
    }
