public class ClassX {
	/**
	 * Redirige al usuario a una URL de destino.
	 * 
	 * La función valida el destino contra una lista negra de dominios maliciosos conocidos.
	 */

	final String BLACKLIST_FILE_NAME = "blackList.txt";
	final String BLACKLIST_PATH = "/blacklist/";
	final String BLANK = "";

	private boolean isOnBlackList(String destination) {
		String[] blackListFileAsArray = getClass().getResource(BLACKLIST_FILE_NAME).getFile().toString()
			.split("[\\n]+");
		for (String string : blackListFileAsArray) {
			if (destination.contains(BLACKLIST_PATH + string)) {
				return true;
			}		
	    }
		return false;
	}

	boolean allowUserToGo(String destination, HttpServletResponse response) throws java.io.IOException {
		if (isOnBlackList(destination)) {
			response.sendRedirect("https://www.notAvailable.com/");
			return false;
		} else {
			response.sendRedirect(destination);
			return true;
		}
	}
}
