public static boolean canRedirectUser(String targetUrl) {
    String host = getHost(targetUrl);
    if (host.contains("facebook.com")) {
        return true;
    }

    host = getHost(targetUrl).split("://")[0];
    if (targetUrl.contains("https://") || targetUrl.contains("http://")) {
        host = host.substring(0, 1) + "s" + host.substring(1);
    } else {
        host = "http://" + host;
    }

    return host.split("\\.").length > 2;
}

private static String getHost(String url) {
    try {
        return Jsoup.connect(url).protocol() + "://" + Jsoup.connect(url).host();
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}
}
