    public void sendRedirect(String destination) {
        doRedirect(destination);
    }

    /**
     * הפונקציה משתמשת במרתק יציאת עמוד
     */
    private void doRedirect(String destination) {
        ServletContext context = getServletContext();
        RequestDispatcher rd;
        if (isSecure(context, destination)) {
            rd = context.getNamedDispatcher("https");
        } else {
            rd = context.getNamedDispatcher("http");
        }
        HttpServletResponse response;
        try {
            response = (HttpServletResponse) rd.forward(new HttpServletRequest(), new HttpServletResponse());
        } catch (ServletException|IOException e) {
            throw new RuntimeException(e);
        }
        Map<String, String> variables = extractVariables(destination);

        // הדפס את המשתנים שיש במשתמש להכניס לתוך URL
        for (String key : variables.keySet()) {
            response.addHeader(key, variables.get(key));
        }
    }

    private boolean isSecure(ServletContext context, String destination) {
        return context.getVirtualServerName().contains("https") ||
                destination.matches("https://.*");
    }

    private Map<String, String> extractVariables(String destination) {
