class Point {

    private double x;
    private double y;
    private double z;

    private Point(double _x, double _y, double _z) {
        x = _x;
        y = _y;
        z = _z;
    }

    static public double computeDistance(double x, double y) {
        return Math.sqrt(x * x + y * y);
    }

    public double norm() {
        return (x * x + y * y + z * z);
    }

    public static int getDistance(Point p) {
        return Math.abs(Point.computeDistance(p.x, p.y));
    }

    public boolean equals(Point p1) {
        return p1.x == this.x && p1.y == this.y && p1.z == this.z;
    }
}
