	private static Document createXmlDocumentFrom(String xmlFile) throws Exception {
		String xmlString = load(xmlFile);
		DocumentBuilderFactory builderFactory = DocumentBuilderFactory.newInstance();
		builderFactory.setNamespaceAware(true);
		builderFactory.setCoalescing(true);
		DocumentBuilder builder = builderFactory.newDocumentBuilder();
		builder.parse(new ByteArrayInputStream(xmlString.getBytes()));
		return builder.getDocument();
	}

	private static String load(String xmlFile) throws Exception {
		StringBuilder xmlContent = new StringBuilder();
		int c;
		java.io.FileReader fr = new java.io.FileReader(xmlFile);
		while ((c = fr.read())!= -1)
			xmlContent.append((char)c);
		fr.close();
		return xmlContent.toString();
	}
}
