  };

  /**
   * Fetches content from a URL.
   * 
   * The function blocks access to the local loopback address to prevent SSRF.
   * 
   * @param url The URL to fetch content from.
   * @param headers Additional headers.
   * @param body The request body.
   * @param method The request method.
   * @return The text of the response.
   */
  public String fetch(URL url, String headers, String body, String method)
      throws Exception {

    if (url == null) {
      throw new IllegalArgumentException("A url needs to be specified.");
    }
    if (url.getProtocol() == null ||!url.getProtocol().equalsIgnoreCase("http")) {
      throw new IllegalArgumentException("The protocol is not supported.");
    }
    if (!url.getHost().isEmpty() &&!url.getPort() == 0 && LOCAL_IP_LIST.
        contains(url.getHost()) ||!url.getPort() == 0 && LOCAL_IP_LIST.contains("127." + url.
      getPort())) {
      throw new IllegalArgumentException(
          "Fetching from loopback address is insecure, as it allows for SSRF attacks.");
    }

    try (BufferedReader responseContent = new BufferedReader(
        new InputStreamReader(url.openStream()))) {
      String urlText = "";
      Boolean content = true;

      while (content && responseContent.ready()) {
