public class Solution {
    class ListNode {
        int val;
        ListNode next;

        ListNode(int x) {
            val = x;
            next = null;
        }
    }

    public ListNode deleteDuplicates(ListNode head) {
        if (head == null) {
            return head;
        }
        ListNode prev = head;
        ListNode cur = head.next;
        while (cur!= null && cur.next!= null) {
            if (prev.val!= cur.val) {
                prev = cur;
                cur = cur.next;
            } else {
                head = cur.next;
                break;
            }
        }
        if (prev!= head) {
            return head;
        }

        for (ListNode t = prev; t!= null && t.next!= null; t = t.next) {
            ListNode c2n = t.next;
            if (c2n.val == t.val) {
                t.next = c2n.next;
            } else {
                t.next = c2n;
            }
        }
        return head;
    }

