import { Form, FormValues } from "antd/lib/form"

export function validationSchema<T>(
  errors: T,
  initialValues: FormValues<T>,
  form: Form<FormValues<T>>
) {
  return {
    validator: (rules, value) => {
      const errors = {} as any
      const { fieldName } = rules
      const name = fieldName.split("[").join(".")

      try {
        const initialValue = initialValues[name]

        if (name && initialValue == null &&!value) {
          errors[fieldName] = [new Error("Please enter a value")]
        }
      } catch (error) {
        // pass
      }

      const fieldErrors = errors[fieldName] || []
      if (errors[fieldName].length < 1) {
        form.validateFields()
      }
    },
  }
}
